def can_reach(s, min_jump, max_jump):
    n = len(s)
    dp = [False] * n
    dp[0] = True
    window_count = 0

    for i in range(1, n):
        if i >= min_jump:
            window_count += 1 if dp[i - min_jump] else 0
        if i > max_jump:
            window_count -= 1 if dp[i - max_jump - 1] else 0
        dp[i] = s[i] == '0' and window_count > 0

    return dp[n - 1]

